insert into public.dialogues (key, speaker_external_id, source_path, source_metadata) select key, speaker_external_id, source_path, source_metadata from jsonb_to_recordset($seed$[{"key":"personal_pronouns_q01_finish","speaker_external_id":"Village Head","source_path":"_registry\\dialogues\\personal_pronouns.yaml","source_metadata":{}},{"key":"personal_pronouns_q01_start","speaker_external_id":"Village Head","source_path":"_registry\\dialogues\\personal_pronouns.yaml","source_metadata":{}},{"key":"personal_pronouns_q02_finish","speaker_external_id":"Little Boy","source_path":"_registry\\dialogues\\personal_pronouns.yaml","source_metadata":{}},{"key":"personal_pronouns_q02_start","speaker_external_id":"Little Boy","source_path":"_registry\\dialogues\\personal_pronouns.yaml","source_metadata":{}},{"key":"personal_pronouns_q03_finish","speaker_external_id":"Village Head","source_path":"_registry\\dialogues\\personal_pronouns.yaml","source_metadata":{}},{"key":"personal_pronouns_q03_start","speaker_external_id":"Village Head","source_path":"_registry\\dialogues\\personal_pronouns.yaml","source_metadata":{}},{"key":"personal_pronouns_q04_finish","speaker_external_id":"Little Boy","source_path":"_registry\\dialogues\\personal_pronouns.yaml","source_metadata":{}},{"key":"personal_pronouns_q04_start","speaker_external_id":"Little Boy","source_path":"_registry\\dialogues\\personal_pronouns.yaml","source_metadata":{}},{"key":"personal_pronouns_q05_finish","speaker_external_id":"Village Head","source_path":"_registry\\dialogues\\personal_pronouns.yaml","source_metadata":{}},{"key":"personal_pronouns_q05_start","speaker_external_id":"Village Head","source_path":"_registry\\dialogues\\personal_pronouns.yaml","source_metadata":{}}]$seed$::jsonb) as entries(key text, speaker_external_id text, source_path text, source_metadata jsonb) on conflict (key) do update set speaker_external_id = excluded.speaker_external_id, source_path = excluded.source_path, source_metadata = excluded.source_metadata, updated_at = now();
insert into public.dialogue_lines (dialogue_id, locale, line_order, content, line_format) select dialogues.id, lines.locale, lines.line_order, lines.content, lines.line_format from jsonb_to_recordset($seed$[{"dialogue_key":"personal_pronouns_q01_finish","locale":"he","line_order":0,"content":"התמונה הראשונה נכנסת עכשיו בחצי דף. זה עובד.","line_format":"plain_text"},{"dialogue_key":"personal_pronouns_q01_finish","locale":"he","line_order":1,"content":"לכו אל הילד הקטן, הוא יושב ליד השולחן עם המחברת. תראו לו מה למדנו.","line_format":"plain_text"},{"dialogue_key":"personal_pronouns_q01_start","locale":"he","line_order":0,"content":"מחר בערב יש הצגה בפארק, וכל הכפר מגיע. יש רק בעיה אחת.","line_format":"plain_text"},{"dialogue_key":"personal_pronouns_q01_start","locale":"he","line_order":1,"content":"הילד הקטן כתב את כל המחזה לבד, אבל הוא כתב כל שם שוב ושוב: Dan is here. Dan is happy. Dan is the king.","line_format":"plain_text"},{"dialogue_key":"personal_pronouns_q01_start","locale":"he","line_order":2,"content":"הדפים במחברת נגמרו באמצע, וסוף ההצגה עוד לא כתוב.","line_format":"plain_text"},{"dialogue_key":"personal_pronouns_q01_start","locale":"he","line_order":3,"content":"יש פתרון. כינוי גוף = pronoun. זו מילה קצרה שבאה במקום שם. במקום Dan is the king אפשר לכתוב He is the king.","line_format":"plain_text"},{"dialogue_key":"personal_pronouns_q01_start","locale":"he","line_order":4,"content":"נתחיל בשתי מילים. I = אני, כשמדברים על עצמי. You = אתה או את, כשמדברים אל מישהו.","line_format":"plain_text"},{"dialogue_key":"personal_pronouns_q01_start","locale":"he","line_order":5,"content":"בואו נכתוב מחדש את התמונה הראשונה.","line_format":"plain_text"},{"dialogue_key":"personal_pronouns_q02_finish","locale":"he","line_order":0,"content":"מדהים. עכשיו כל התמונה השנייה נכנסת בדף אחד, ועוד נשאר לי מקום.","line_format":"plain_text"},{"dialogue_key":"personal_pronouns_q02_finish","locale":"he","line_order":1,"content":"ראש הכפר מסדר עכשיו את האביזרים של ההצגה. לכו אליו, הוא נתקע עם הרשימה.","line_format":"plain_text"},{"dialogue_key":"personal_pronouns_q02_start","locale":"he","line_order":0,"content":"כתבתי את ההצגה לבד, ואף שחקן לא מצליח לקרוא אותה.","line_format":"plain_text"},{"dialogue_key":"personal_pronouns_q02_start","locale":"he","line_order":1,"content":"בתמונה השנייה יש זמר ורקדנית, ואני כתבתי את השמות שלהם שבע עשרה פעמים.","line_format":"plain_text"},{"dialogue_key":"personal_pronouns_q02_start","locale":"he","line_order":2,"content":"ראש הכפר אמר שיש מילה קצרה לבן ומילה קצרה לבת.","line_format":"plain_text"},{"dialogue_key":"personal_pronouns_q02_start","locale":"he","line_order":3,"content":"He = הוא, על בן. She = היא, על בת.","line_format":"plain_text"},{"dialogue_key":"personal_pronouns_q02_start","locale":"he","line_order":4,"content":"בואו נכתוב את התמונה השנייה יחד.","line_format":"plain_text"},{"dialogue_key":"personal_pronouns_q03_finish","locale":"he","line_order":0,"content":"הרשימה מוכנה וכל האביזרים בארגז. תודה לכם.","line_format":"plain_text"},{"dialogue_key":"personal_pronouns_q03_finish","locale":"he","line_order":1,"content":"נשארה התמונה האחרונה, זו עם הקהל הגדול. הילד הקטן נתקע בה מאתמול. לכו אליו.","line_format":"plain_text"},{"dialogue_key":"personal_pronouns_q03_start","locale":"he","line_order":0,"content":"יש לי כאן ארגז אביזרים: כובע, כתר ומטריה. לאף אחד מהם אין שם.","line_format":"plain_text"},{"dialogue_key":"personal_pronouns_q03_start","locale":"he","line_order":1,"content":"It = זה. משתמשים במילה הזאת על חפץ או על בעל חיים, אף פעם לא על אדם.","line_format":"plain_text"},{"dialogue_key":"personal_pronouns_q03_start","locale":"he","line_order":2,"content":"ויש עוד מילה שאני צריך. We = אנחנו, כשאני מדבר על עצמי ועל כל הלהקה יחד.","line_format":"plain_text"},{"dialogue_key":"personal_pronouns_q03_start","locale":"he","line_order":3,"content":"בואו נסדר את הרשימה לפני החזרה האחרונה.","line_format":"plain_text"},{"dialogue_key":"personal_pronouns_q04_finish","locale":"he","line_order":0,"content":"כתבתי את המילה האחרונה, ונשארו לי שני דפים ריקים. סיימנו את המחזה!","line_format":"plain_text"},{"dialogue_key":"personal_pronouns_q04_finish","locale":"he","line_order":1,"content":"ראש הכפר כבר מדליק את הפנסים על הבמה. הערב מתחילה ההצגה.","line_format":"plain_text"},{"dialogue_key":"personal_pronouns_q04_start","locale":"he","line_order":0,"content":"בתמונה האחרונה עומדים עשרים אנשים על הבמה, ואני לא יכול לכתוב עשרים שמות.","line_format":"plain_text"},{"dialogue_key":"personal_pronouns_q04_start","locale":"he","line_order":1,"content":"כשמדברים על יותר מאדם אחד יש מילה אחת שמספיקה לכולם.","line_format":"plain_text"},{"dialogue_key":"personal_pronouns_q04_start","locale":"he","line_order":2,"content":"They = הם או הן. לא משנה אם אלה בנים או בנות, המילה נשארת אותו דבר.","line_format":"plain_text"},{"dialogue_key":"personal_pronouns_q04_start","locale":"he","line_order":3,"content":"בואו נסיים את המחזה.","line_format":"plain_text"},{"dialogue_key":"personal_pronouns_q05_finish","locale":"he","line_order":0,"content":"ההצגה נגמרה והקהל עמד ומחא כפיים. הילד הקטן לא מפסיק לחייך.","line_format":"plain_text"},{"dialogue_key":"personal_pronouns_q05_finish","locale":"he","line_order":1,"content":"כל המחזה נכנס למחברת אחת, כי ידעתם להחליף כל שם במילה הקצרה הנכונה.","line_format":"plain_text"},{"dialogue_key":"personal_pronouns_q05_finish","locale":"he","line_order":2,"content":"קבלו עשרה מטבעות עכשיו. סיימתם את הסיפור בהצלחה!","line_format":"plain_text"},{"dialogue_key":"personal_pronouns_q05_start","locale":"he","line_order":0,"content":"הקהל יושב, הפנסים דולקים, וההצגה מתחילה בעוד רגע.","line_format":"plain_text"},{"dialogue_key":"personal_pronouns_q05_start","locale":"he","line_order":1,"content":"בתמונה הזאת כל המילים מעורבבות: I, You, He, She, It, We, They.","line_format":"plain_text"},{"dialogue_key":"personal_pronouns_q05_start","locale":"he","line_order":2,"content":"הפעם תרכיבו את המשפטים לבד, בלי עזרה, ואז תגידו את השורות שלכם בקול על הבמה.","line_format":"plain_text"}]$seed$::jsonb) as lines(dialogue_key text, locale text, line_order integer, content text, line_format text) join public.dialogues on dialogues.key = lines.dialogue_key on conflict (dialogue_id, locale, line_order) do update set content = excluded.content, line_format = excluded.line_format;
